// Memória permanente para vagas Dev & TI
const staticData = $getWorkflowStaticData('global');
staticData.seenDevJobIds = staticData.seenDevJobIds || [];

const novasVagas = [];

for (const item of $input.all()) {
  const job = item.json;
  const id = job.job_id;

  if (!id || staticData.seenDevJobIds.includes(id)) {
    continue;
  }

  // 1. Remoto (Brasil todo)
  const isRemote = job.job_is_remote === true || 
                   /remoto|home\s*office/i.test(job.job_title || '') ||
                   /100%\s*remoto|trabalho\s*remoto/i.test(job.job_description || '');

  // 2. Presencial (Apenas Feira de Santana)
  const isFeira = /feira\s*de\s*santana|fsa/i.test(job.job_city || '') ||
                  /feira\s*de\s*santana|fsa/i.test(job.job_location || '') ||
                  /feira\s*de\s*santana/i.test(job.job_description || '');

  if (isRemote || isFeira) {
    staticData.seenDevJobIds.push(id);
    novasVagas.push(item);
  }
}

if (staticData.seenDevJobIds.length > 200) {
  staticData.seenDevJobIds = staticData.seenDevJobIds.slice(-200);
}

return novasVagas;

