// Memória permanente para vagas Administrativas FSA
const staticData = $getWorkflowStaticData('global');
staticData.seenAdminJobIds = staticData.seenAdminJobIds || [];

const novasVagasAdmin = [];

for (const item of $input.all()) {
  const job = item.json;
  const id = job.job_id;

  if (!id || staticData.seenAdminJobIds.includes(id)) {
    continue;
  }

  const title = (job.job_title || '').toLowerCase();
  const desc = (job.job_description || '').toLowerCase();
  const city = (job.job_city || '').toLowerCase();
  const location = (job.job_location || '').toLowerCase();

  // 1. REGRA: EXCLUSIVAMENTE PRESENCIAL (SEM VAGA ONLINE/REMOTA)
  const isRemote = job.job_is_remote === true || 
                   /remoto|home\s*office|híbrido|hibrido|teletrabalho/.test(title) ||
                   /trabalho\s*remoto|vaga\s*remota|100%\s*home\s*office/.test(desc);
  if (isRemote) {
    continue;
  }

  // 2. REGRA: EXCLUSIVAMENTE EM FEIRA DE SANTANA
  const isFeira = /feira\s*de\s*santana|fsa/.test(city) ||
                  /feira\s*de\s*santana|fsa/.test(location) ||
                  /feira\s*de\s*santana/.test(desc);
  if (!isFeira) {
    continue;
  }

  // 3. REGRA: SEM ME / SEM PJ (Contratação CLT ou Estágio Direto)
  const isMEorPJ = /\b(mei|pj|pessoa\s*jurídica|pessoa\s*juridica|microempresa|micro\s*empreendedor|prestador\s*de\s*serviço|prestador\s*de\s*servico|comissionado|autônomo|autonomo)\b/.test(desc) ||
                   /\b(mei|pj)\b/.test(title);
  if (isMEorPJ) {
    continue;
  }

  staticData.seenAdminJobIds.push(id);
  novasVagasAdmin.push(item);
}

if (staticData.seenAdminJobIds.length > 200) {
  staticData.seenAdminJobIds = staticData.seenAdminJobIds.slice(-200);
}

return novasVagasAdmin;

